mapper.select:
SELECT
TOP_JOB_CODE
,TOP_JOB_NAME

FROM TOP_JOB
WHERE TOP_JOB_CODE = #{topJobCode}
AND TOP_JOB_NAME = #{topJobName}

mapper.update:
UPDATE TOP_JOB
SET TOP_JOB_NAME = #{topJobName}
WHERE
TOP_JOB_CODE = #{topJobCode}

mapper.delete:
